#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    long long n;
    cin >> n;

    bool prime = n >= 2;
    for (long long d = 2; d * d <= n; d++) {
        if (n % d == 0) {
            prime = false;
            break;
        }
    }
    cout << (prime ? "prime" : "not prime") << endl;

    return 0;
}

code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();

        boolean prime = n >= 2;
        for (long d = 2; d * d <= n; d++) {
            if (n % d == 0) {
                prime = false;
                break;
            }
        }
        System.out.println(prime ? "prime" : "not prime");
    }
}
